// M26-A.4  NCO complex mixer.
//
//   y[n] = x[n] * exp(-j 2pi (f/fs) n)
//
// Per M26_FIXED_POINT_CONTRACT.md §4: a 32-bit phase accumulator increments by
// `phase_inc = round(f/fs * 2^32)` each sample (mod 2^32 wrap is legal, not an
// overflow).  The top 10 phase bits index a quarter-wave sin LUT (256x16 Q1.15,
// `m26_sin_lut.mem`, generated by the same formula as the C++ build_sin_lut()), with
// quadrant folding to reconstruct full cos/sin.  The complex product is formed in
// Q2.30 then rounded (round-half-away) and symmetrically saturated to Q1.15.
//
//   re = I*cos + Q*sin ,  im = Q*cos - I*sin     (negative-frequency convention)
module m26_nco (
    input  logic        clk,
    input  logic        rst_n,
    input  logic        bypass,
    input  logic [31:0] phase_inc,       // Delta_phi = round(f/fs * 2^32)
    input  logic        s_axis_tvalid,
    output logic        s_axis_tready,
    input  logic [31:0] s_axis_tdata,
    input  logic        s_axis_tlast,
    output logic        m_axis_tvalid,
    input  logic        m_axis_tready,
    output logic [31:0] m_axis_tdata,
    output logic        m_axis_tlast
);
  import m26_fxp_pkg::*;

  logic [15:0] lut [0:255];
  logic [31:0] phase;
  logic        out_valid;

  initial $readmemh("m26_sin_lut.mem", lut);

  wire [9:0] top  = phase[31:22];
  wire [1:0] quad = top[9:8];
  wire [7:0] idx  = top[7:0];
  wire [15:0] s0  = lut[idx];        // sin(idx*pi/512)
  wire [15:0] s1  = lut[255 - idx];  // ~cos(idx*pi/512)

  logic signed [15:0] cos_v, sin_v;
  always_comb begin
    case (quad)
      2'd0:    begin cos_v =  $signed(s1); sin_v =  $signed(s0); end
      2'd1:    begin cos_v = -$signed(s0); sin_v =  $signed(s1); end
      2'd2:    begin cos_v = -$signed(s1); sin_v = -$signed(s0); end
      default: begin cos_v =  $signed(s0); sin_v = -$signed(s1); end
    endcase
  end

  wire signed [15:0] i_in = $signed(s_axis_tdata[15:0]);
  wire signed [15:0] q_in = $signed(s_axis_tdata[31:16]);

  wire signed [31:0] m_ii = i_in * cos_v;   // Q2.30
  wire signed [31:0] m_iq = i_in * sin_v;
  wire signed [31:0] m_qi = q_in * cos_v;
  wire signed [31:0] m_qq = q_in * sin_v;
  wire signed [32:0] re_sum = m_ii + m_qq;  // I*cos + Q*sin
  wire signed [32:0] im_sum = m_qi - m_iq;  // Q*cos - I*sin

  assign s_axis_tready = !out_valid || m_axis_tready;
  assign m_axis_tvalid = out_valid;

  always_ff @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      phase     <= 32'd0;
      out_valid <= 1'b0;
    end else begin
      if (s_axis_tready && s_axis_tvalid) begin
        phase <= phase + phase_inc;   // use current phase, then advance
        if (bypass)
          m_axis_tdata <= s_axis_tdata;
        else
          m_axis_tdata <= {rshift_round_sat16(im_sum, 15), rshift_round_sat16(re_sum, 15)};
        m_axis_tlast <= s_axis_tlast;
        out_valid    <= 1'b1;
      end else if (m_axis_tready && out_valid) begin
        out_valid <= 1'b0;
      end
    end
  end

endmodule
